<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_tasks.view');$pdo=db();$projectId=(int)($_GET['project_id']??0);$month=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['month']??''))?$_GET['month']:date('Y-m');$first=new DateTimeImmutable($month.'-01');$last=$first->modify('last day of this month');$project=$projectId?pm_fetch_project($pdo,$projectId):null;$projects=pm_project_options($pdo);$where=['t.due_date BETWEEN ? AND ?'];$params=[$first->format('Y-m-d'),$last->format('Y-m-d')];if($projectId){$where[]='t.project_id=?';$params[]=$projectId;}$s=$pdo->prepare("SELECT t.*,p.name project_name,p.color project_color,u.name assigned_name,c.company_name FROM project_tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=t.assigned_to WHERE ".implode(' AND ',$where)." ORDER BY t.due_date,t.priority DESC");$s->execute($params);$rows=$s->fetchAll();$by=[];foreach($rows as$r)$by[$r['due_date']][]=$r;$startGrid=$first->modify('-'.((int)$first->format('N')-1).' days');$pageTitle='Calendario de proyectos';$calendarUrl=app_url('project_calendar.php?project_id='.$projectId.'&month='.$month);$shareText='Calendario de proyectos · '.$first->format('m/Y').' · '.$calendarUrl;$shareEnabled=(string)setting('calendar_share_enabled','1')==='1';require __DIR__.'/includes/header.php';if($project)echo pm_project_tabs($projectId,'calendar');?>
<div class="project-hero compact"><div><span class="eyebrow">CALENDARIO DE PROYECTOS</span><h2><?=e($first->format('m/Y'))?></h2><p>Fechas de entrega, compromisos y calendario compartible del equipo.</p></div><div class="actions"><a class="btn btn-light btn-small" href="?project_id=<?=$projectId?>&month=<?=$first->modify('-1 month')->format('Y-m')?>">← Mes anterior</a><a class="btn btn-light btn-small" href="?project_id=<?=$projectId?>&month=<?=$first->modify('+1 month')->format('Y-m')?>">Mes siguiente →</a><form method="get"><input type="hidden" name="month" value="<?=e($month)?>"><select name="project_id" onchange="this.form.submit()"><option value="0">Todos los proyectos</option><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form></div></div>
<?php if($shareEnabled):?><div class="calendar-sharebar"><strong><?=crm_icon('share')?> Compartir calendario</strong><a class="share-chip" href="project_calendar_export.php?project_id=<?=$projectId?>&month=<?=e($month)?>"><?=crm_icon('calendar')?> .ICS <small>Apple / Outlook</small></a><a class="share-chip" target="_blank" rel="noopener" href="https://wa.me/?text=<?=rawurlencode($shareText)?>"><?=crm_icon('whatsapp')?> WhatsApp</a><a class="share-chip" href="mailto:?subject=<?=rawurlencode('Calendario de proyectos '.$first->format('m/Y'))?>&body=<?=rawurlencode($shareText)?>"><?=crm_icon('mail')?> Email</a><button type="button" class="share-chip" data-copy-text="<?=e($calendarUrl)?>"><?=crm_icon('open')?> Copiar enlace</button><span class="table-sub">Las tareas pueden abrirse y exportarse individualmente.</span></div><?php endif;?>
<section class="pm-calendar"><div class="pm-calendar-head"><?php foreach(['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'] as$d):?><strong><?=$d?></strong><?php endforeach;?></div><div class="pm-calendar-grid"><?php for($i=0;$i<42;$i++):$day=$startGrid->modify('+'.$i.' days');$key=$day->format('Y-m-d');$outside=$day->format('m')!==$first->format('m');?><div class="pm-calendar-day <?=$outside?'outside':''?> <?=$key===date('Y-m-d')?'today':''?>"><b><?=$day->format('d')?></b><?php foreach($by[$key]??[] as$t):$google='https://calendar.google.com/calendar/render?action=TEMPLATE&text='.rawurlencode($t['title']).'&dates='.date('Ymd',strtotime($t['due_date'])).'/'.date('Ymd',strtotime($t['due_date'].' +1 day')).'&details='.rawurlencode('Proyecto: '.$t['project_name'].' · '.($t['description']??''));?><a href="project_task_form.php?id=<?=$t['id']?>" class="pm-calendar-task priority-<?=e($t['priority'])?>" style="--project-color:<?=e($t['project_color'])?>" title="Abrir tarea · <?=e($t['assigned_name']?:'Sin responsable')?>"><span><?=e($t['title'])?></span><small><?=e($t['project_name'])?></small><span class="task-share">↗</span></a><?php if($shareEnabled):?><div class="icon-actions calendar-event-actions"><a class="icon-action mini" target="_blank" href="<?=e($google)?>" title="Agregar a Google Calendar">G</a><a class="icon-action mini" href="project_calendar_export.php?task_id=<?=$t['id']?>" title="Apple / Outlook / ICS"><?=crm_icon('calendar')?></a></div><?php endif;?><?php endforeach;?></div><?php endfor;?></div></section><script>document.querySelectorAll('[data-copy-text]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copyText);b.textContent='✓ Enlace copiado';}catch(e){prompt('Copia este enlace:',b.dataset.copyText)}}));</script>
<?php require __DIR__.'/includes/footer.php';?>
